  ((SELECT id FROM lms_pa_forms WHERE code = 'A' AND version = 1), 'B2', 'behaviour', 'single_choice', (SELECT id FROM lms_pa_domains WHERE code = 'data'), 'behaviours', NULL, 'Dalam sebulan terakhir: sebelum memasukkan data ke AI, saya memastikan data itu boleh dibagikan sesuai kebijakan kantor.', FALSE, TRUE, NULL, 31),
  ((SELECT id FROM lms_pa_forms WHERE code = 'A' AND version = 1), 'B3', 'behaviour', 'single_choice', (SELECT id FROM lms_pa_domains WHERE code = 'tools_methods'), 'behaviours', NULL, 'Dalam sebulan terakhir: saya memperbaiki prompt atau hasilnya beberapa kali sampai sesuai standar, bukan menerima jawaban pertama.', FALSE, FALSE, NULL, 32),
